                }
                .ai-thumb-wrapper.is-featured {
                    border-color: #9b51e0;
                    box-shadow: 0 0 0 2px rgba(155,81,224,0.3);
                }
                .ai-thumb-wrapper.is-included {
                    border-color: #2271b1;
                }
                .ai-thumb-img {
                    width: 100%; 
                    height: 100%; 
                    object-fit: cover;
                }
