                .ai-status-error { background: #fbeae1; color: #d63638; border: 1px solid #f5c2c2; }
                .ai-error-text { display: block; color: #b32d2e; font-size: 11px; margin-top: 4px; font-weight: normal; max-width: 300px; word-break: break-word; }
