            <div id="ai_action_zone" style="display: none; border-top: 1px solid #eee; padding-top: 20px;">
                <h2 style="margin-top: 0;">Krok 2: Wyślij gotowy produkt do AI</h2>
                <button type="button" class="button button-primary button-large" id="ai_submit_product_btn" style="background: #9b51e0; border-color: #883cd1; font-size: 16px; padding: 5px 30px; height: auto;">
                    Dodaj produkt do wygenerowania opisu
                </button>
