            <div id="ai_upload_status" style="margin-top: 15px; font-weight: bold; color: #555;"></div>
        </div>

        <h2 style="margin-top: 40px;">Produkty aktualnie przetwarzane przez n8n</h2>
        <table class="wp-list-table widefat fixed striped">
            <thead>
                <tr>
                    <th style="width: 100px;">Miniaturka</th>
                    <th>Tymczasowy tytuł / ID</th>
                    <th>Liczba zdjęć do AI</th>
                    <th>Status bota</th>
                    <th style="width: 150px;">Akcje</th>
                </tr>
            </thead>
            <tbody id="ai_processing_table">
                <tr><td colspan="5">Ładowanie kolejki AI...</td></tr>
            </tbody>
        </table>
