    <script type="text/javascript">
    jQuery(document).ready(function($) {
        var mediaUploader;
        var productImages = []; 
        var featuredImageId = null; 

        function renderPreviews() {
            var container = $('#ai_preview_container');
            container.empty();

            if (productImages.length === 0) {
                $('#ai_action_zone').hide();
                featuredImageId = null;
                return;
            }

            if (!featuredImageId && productImages.length > 0) {
                featuredImageId = productImages[0].id;
            }

            var sentToAiCount = 0;

            productImages.forEach(function(img) {
                var isFeatured = (img.id === featuredImageId);
                var activeClass = '';
                var badge = '';

                if (isFeatured) {
                    activeClass = ' is-featured';
                    badge = '<div class="ai-thumb-badge">GŁÓWNE (AI 1/3)</div>';
                    sentToAiCount++;
                } else if (sentToAiCount < 3) {
                    activeClass = ' is-included';
                    sentToAiCount++;
                    badge = '<div class="ai-thumb-badge gallery-badge">DO AI (' + sentToAiCount + '/3)</div>';
                } else {
                    badge = '<div class="ai-thumb-badge ignored-badge">IGNOROWANE</div>';
                }

                container.append(
                    '<div class="ai-thumb-wrapper' + activeClass + '" data-id="' + img.id + '">' +
                        '<div class="ai-thumb-delete" title="Usuń zdjęcie">&times;</div>' +
                        '<img src="' + img.url + '" class="ai-thumb-img">' +
                        badge +
                    '</div>'
                );
            });

            $('#ai_action_zone').slideDown();
        }

        $('#ai_select_photos_btn').on('click', function(e) {
            e.preventDefault();
            mediaUploader = wp.media({
                title: 'Dołóż zdjęcia do obecnego produktu',
                button: { text: 'Dodaj do zestawu' },
                multiple: true
            });

            mediaUploader.on('select', function() {
                var attachments = mediaUploader.state().get('selection').toJSON();
                attachments.forEach(function(attachment) {
                    var exists = productImages.some(function(item) { return item.id === attachment.id; });
                    if (!exists) {
                        productImages.push({
                            id: attachment.id,
                            url: attachment.url
                        });
                    }
                });
                $('#ai_upload_status').empty();
                renderPreviews();
            });
            mediaUploader.open();
        });

        $('#ai_preview_container').on('click', '.ai-thumb-wrapper', function(e) {
            var clickedId = $(this).data('id');
            if ($(e.target).hasClass('ai-thumb-delete')) {
                e.stopPropagation();
                productImages = productImages.filter(function(item) { return item.id !== clickedId; });
                if (featuredImageId === clickedId) { featuredImageId = null; }
                renderPreviews();
                return;
            }
            featuredImageId = clickedId;
            renderPreviews();
        });

        $('#ai_submit_product_btn').on('click', function(e) {
            e.preventDefault();
            if (productImages.length === 0) return;

            var finalIds = [featuredImageId];
            var addedCount = 1;

            for (var i = 0; i < productImages.length; i++) {
                if (addedCount >= 3) break;
                if (productImages[i].id !== featuredImageId) {
                    finalIds.push(productImages[i].id);
                    addedCount++;
                }
            }

            $('#ai_upload_status').html('<span style="color: #9b51e0;">Rejestracja produktu i generowanie galerii...</span>');

            $.post(ajaxurl, {
                action: 'ai_create_bulk_products',
                image_ids: finalIds
            }, function(response) {
                if(response.success) {
                    $('#ai_upload_status').html('<span style="color: green;">Produkt pomyślnie dodany do n8n (Wysłano maksymalnie 3 pasujące zdjęcia)!</span>');
                    productImages = [];
                    featuredImageId = null;
                    renderPreviews();
                    loadAiQueue();
                } else {
                    $('#ai_upload_status').text('❌ Wystąpił błąd podczas zapisu.');
                }
            });
        });

        // REAKCJA NA PRZYCISKI AKCJI W TABELI (USUŃ / PONÓW)
        $('#ai_processing_table').on('click', '.ai-row-action-btn', function(e) {
            e.preventDefault();
            var btn = $(this);
            var actionType = btn.data('action');
            var productId = btn.data('id');

            btn.prop('disabled', true).text('...');

            $.post(ajaxurl, {
                action: 'ai_handle_row_action',
                sub_action: actionType,
                product_id: productId
            }, function(response) {
                if(response.success) {
                    loadAiQueue();
                } else {
                    alert('Operacja nie powiodła się.');
                    btn.prop('disabled', false).text(actionType === 'retry' ? 'Ponów' : 'Usuń');
                }
            });
        });

        function loadAiQueue() {
            $.post(ajaxurl, { action: 'ai_get_processing_queue' }, function(response) {
                if(response.success && response.data.length > 0) {
                    var html = '';
                    response.data.forEach(function(item) {
                        var statusHtml = '';
                        var actionsHtml = '';

                        if(item.status === 'error') {
                            statusHtml = '<span class="ai-badge-status ai-status-error">Błąd podczas generowania</span>' +
                                         '<span class="ai-error-text"> Powód: ' + item.error_msg + '</span>';

                            actionsHtml = '<button class="button button-secondary ai-row-action-btn" data-action="retry" data-id="' + item.id + '" style="margin-right:5px; color: green; border-color:green;">Ponów</button>' +
                                          '<button class="button button-link delete ai-row-action-btn" data-action="delete" data-id="' + item.id + '" style="color: #d63638;">Usuń</button>';
                        } else {
                            statusHtml = '<span class="ai-badge-status ai-status-waiting">Czeka w kolejce bota</span>';
                            actionsHtml = '<span style="color:#999; font-style:italic;">Brak (w procesie)</span>';
                        }

                        html += '<tr>' +
                                '<td><img src="' + item.thumb + '" style="max-width: 60px; height: auto; border-radius: 4px;"></td>' +
                                '<td><strong>' + item.title + '</strong> (ID: ' + item.id + ')</td>' +
                                '<td>' + item.image_count + ' / 3 zdjęć</td>' +
                                '<td>' + statusHtml + '</td>' +
                                '<td>' + actionsHtml + '</td>' +
                                '</tr>';
                    });
                    $('#ai_processing_table').html(html);
                } else {
                    $('#ai_processing_table').html('<tr><td colspan="5">Obecnie żadne produkty nie czekają w kolejce bota. Wszystko przetworzone!</td></tr>');
                }
            });
        }
        loadAiQueue();
        setInterval(loadAiQueue, 5000);
    });
    </script>
    <?php
}

// 3. Silnik PHP: Tworzenie JEDNEGO produktu z maks 3 zdjęciami
add_action( 'wp_ajax_ai_create_bulk_products', 'ai_create_bulk_products_callback' );
function ai_create_bulk_products_callback() {
    if ( !isset($_POST['image_ids']) || !is_array($_POST['image_ids']) ) {
        wp_send_json_error();
    }

    $images = array_map('intval', $_POST['image_ids']);
    $images = array_slice($images, 0, 3);

    $featured_image_id = array_shift($images); 
    $gallery_image_ids = $images; 

    $product = new WC_Product_Simple();
    $product->set_name( 'Produkt AI #' . $featured_image_id );
    $product->set_status( 'draft' ); 
    $product->set_image_id( $featured_image_id ); 

    if ( !empty($gallery_image_ids) ) {
        $product->set_gallery_image_ids( $gallery_image_ids ); 
    }

    $product_id = $product->save();

    // Ustawiamy dwie flagi na starcie
    update_post_meta( $product_id, '_is_ai_generated_draft', 'yes' );
    update_post_meta( $product_id, '_ai_automation_status', 'waiting' );

    wp_send_json_success();
}

// 4. Silnik PHP: Pobieranie danych do tabeli w locie
add_action( 'wp_ajax_ai_get_processing_queue', 'ai_get_processing_queue_callback' );
function ai_get_processing_queue_callback() {
    global $wpdb;
    $results = $wpdb->get_results( "SELECT post_id FROM $wpdb->postmeta WHERE meta_key = '_is_ai_generated_draft' AND meta_value = 'yes'" );

    $data = [];
    foreach ( $results as $row ) {
        $product = wc_get_product( $row->post_id );
        if ( $product ) {
            $gallery = $product->get_gallery_image_ids();
            $total_images = 1 + (is_array($gallery) ? count($gallery) : 0);

            // Pobieramy status automatyzacji oraz ewentualną treść błędu
            $status = get_post_meta( $product->get_id(), '_ai_automation_status', true ) ?: 'waiting';
            $error_msg = get_post_meta( $product->get_id(), '_ai_last_error_message', true ) ?: 'Nieznany błąd serwera LLM.';

            $data[] = [
                'id' => $product->get_id(),
                'title' => $product->get_name(),
                'image_count' => $total_images,
                'thumb' => wp_get_attachment_image_url( $product->get_image_id(), 'thumbnail' ) ?: wc_placeholder_img_src(),
                'status' => $status,
                'error_msg' => $error_msg
            ];
        }
    }
    wp_send_json_success( $data );
}

// NOWOŚĆ: OBSŁUGA AKCJI "USUŃ" LUB "PONÓW" Z POZIOMU TABELI
add_action( 'wp_ajax_ai_handle_row_action', 'ai_handle_row_action_callback' );
function ai_handle_row_action_callback() {
    $sub_action = isset($_POST['sub_action']) ? sanitize_text_field($_POST['sub_action']) : '';
    $product_id = isset($_POST['product_id']) ? intval($_POST['product_id']) : 0;

    if ( !$product_id || !current_user_can('manage_options') ) {
        wp_send_json_error();
    }

    if ( $sub_action === 'delete' ) {
        // Całkowicie usuwamy wadliwy produkt ze sklepu
        wp_delete_post( $product_id, true );
        wp_send_json_success();
    } elseif ( $sub_action === 'retry' ) {
        // Resetujemy status na "waiting", co pozwoli n8n pobrać go ponownie w kolejnym cyklu
        update_post_meta( $product_id, '_ai_automation_status', 'waiting' );
        delete_post_meta( $product_id, '_ai_last_error_message' );
        wp_send_json_success();
    }

    wp_send_json_error();
}

// 5. UKRYWANIE PRODUKTÓW Z DOMYŚLNEJ ZAKŁADKI WOOCOMMERCE
add_action( 'pre_get_posts', 'ai_hide_drafts_from_standard_woocommerce' );
function ai_hide_drafts_from_standard_woocommerce( $query ) {
    if ( is_admin() && $query->is_main_query() && $query->get('post_type') === 'product' ) {
        if ( !isset($_GET['post_status']) || $_GET['post_status'] !== 'ai_queue' ) {
            $meta_query = (array) $query->get('meta_query');
            $meta_query[] = [
                'key'     => '_is_ai_generated_draft',
                'compare' => 'NOT EXISTS'
            ];
            $query->set( 'meta_query', $meta_query );
        }
    }
}

// 6. AUTOMATYCZNE ODBLOKOWANIE (Gdy n8n zakończy sukcesem i zmieni status na pending)
add_action( 'transition_post_status', 'ai_auto_clear_flag_on_status_change', 10, 3 );
function ai_auto_clear_flag_on_status_change( $new_status, $old_status, $post ) {
    if ( $post->post_type === 'product' && $new_status === 'pending' ) {
        delete_post_meta( $post->ID, '_is_ai_generated_draft' );
        delete_post_meta( $post->ID, '_ai_automation_status' );
        delete_post_meta( $post->ID, '_ai_last_error_message' );
    }
}

// NOWOŚĆ: ENDPOINT REST API DLA GLOBALNEGO ERROR TRIGGERA Z n8n
add_action( 'rest_api_init', function () {
    register_rest_route( 'system-ai/v1', '/report-error', array(
        'methods'  => 'POST',
        'callback' => function( WP_REST_Request $request ) {
            $product_id = intval($request->get_param('product_id'));
            $error_msg  = sanitize_text_field($request->get_param('error_message'));

            if ( !$product_id ) {
                return new WP_Error( 'no_id', 'Brak ID produktu', array( 'status' => 400 ) );
            }

            // Aktualizujemy status na 'error' i zapisujemy powód awarii
            update_post_meta( $product_id, '_ai_automation_status', 'error' );
            update_post_meta( $product_id, '_ai_last_error_message', $error_msg );

            return array( 'success' => true );
        },
        'permission_callback' => '__return_true'
    ) );
} );
